mapper.select:
SELECT b.role_name FROM user_role a,role b
WHERE a.role_id = b.role_id
AND a.user_id = #{userId}

SELECT DISTINCT u.id FROM user u INNER JOIN user_role ur ON ur.user_id = u.id INNER JOIN role r ON r.role_id = ur.role_id WHERE u.deleted = 0 AND u.status = 1 AND r.role_name IN
#{roleName}
ORDER BY u.id
